/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PermissionPath =
  | 'admins.read'
  | 'admins.create'
  | 'admins.update'
  | 'admins.delete'
  | 'admins.grant'
  | 'admins.reset_password'
  | 'users.read'
  | 'users.create'
  | 'users.update'
  | 'users.delete'
  | 'posts.read'
  | 'posts.update'
  | 'posts.delete'
  | 'app_config.read'
  | 'app_config.update'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type Admin = {
  id: string
  created_at?: string
  email: string

  first_name: string
  last_name: string
  phone?: string
  avatar_url?: string

  permissions: PermissionPath[]
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminTokenResponse = {
  access_token: string
  refresh_token: string
  admin: Admin
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminUpdatePayload = {
  email?: string
  first_name?: string
  last_name?: string
  phone?: string
  avatar_url?: string | null

  old_password?: string
  new_password?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminCreatePayload = {
  email: string
  password: string

  first_name: string
  last_name: string
  phone?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminProfileUpdatePayload = {
  email?: string
  first_name?: string
  last_name?: string
  phone?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminSortBy = 'EMAIL' | 'FIRST_NAME' | 'LAST_NAME' | 'CREATED_AT'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminSortDirection = 'ASC' | 'DESC'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminsListParams = {
  q?: string
  sort_by?: AdminSortBy
  sort_direction?: AdminSortDirection
  page?: number
  limit?: number
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PermissionNode = {
  id: string
  path: string
  label: string
  description: string
  grantable: boolean
  children: PermissionNode[]
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type User = {
  id: string
  created_at?: string
  email: string
  first_name?: string
  last_name?: string
  email_verified_at?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserAdminCreatePayload = {
  email: string
  password: string

  first_name?: string
  last_name?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserAdminUpdatePayload = {
  email?: string
  first_name?: string | null
  last_name?: string | null
  avatar_url?: string | null
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserSortBy = 'EMAIL' | 'FIRST_NAME' | 'LAST_NAME' | 'CREATED_AT'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserSortDirection = 'ASC' | 'DESC'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UsersListParams = {
  q?: string
  sort_by?: UserSortBy
  sort_direction?: UserSortDirection
  page?: number
  limit?: number
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostMediaType = 'IMAGE' | 'VIDEO'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostMedia = {
  url: string
  type: PostMediaType
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostAuthor = {
  id: string
  email: string
  first_name?: string
  last_name?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type AdminPost = {
  id: string
  created_at?: string
  updated_at?: string
  title: string
  content: string
  media: PostMedia[]
  is_hidden: boolean
  is_saved: boolean
  author: PostAuthor
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostAdminUpdatePayload = {
  title?: string
  content?: string
  media?: PostMedia[]
  is_hidden?: boolean
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostSortBy = 'TITLE' | 'CREATED_AT'

